                .andExpect(jsonPath("$.lateFee").value(500));
    }

    @Test
    void returning_without_a_body_uses_today() throws Exception {
        String loanId = loanBook(registerBook(), registerMember("권나은"), "2026-01-01");
        long expectedOverdueDays = ChronoUnit.DAYS.between(LocalDate.of(2026, 1, 15), LocalDate.now());

        mockMvc.perform(post("/loans/{loanId}/return", loanId))
