import org.springframework.test.web.servlet.MockMvc;

import java.time.LocalDate;
import java.time.temporal.ChronoUnit;

import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

@SpringBootTest
@AutoConfigureMockMvc
class LateFeeApiTest {

    @Autowired
    MockMvc mockMvc;

    @Autowired
    ObjectMapper objectMapper;

    @Test
    void a_loan_can_be_backdated_and_its_due_date_is_14_days_later() throws Exception {
        String loanId = loanBook(registerBook(), registerMember("백지훈"), "2026-01-01");

        mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON)
                        .content(loanBody(registerBook(), registerMember("백지훈"), "2026-01-01")))
                .andExpect(status().isCreated())
                .andExpect(jsonPath("$.loanedAt").value("2026-01-01"))
                .andExpect(jsonPath("$.dueAt").value("2026-01-15"));

        mockMvc.perform(post("/loans/{loanId}/return", loanId)
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"returnedAt\":\"2026-01-15\"}"))
                .andExpect(status().isOk());
    }

    @Test
    void a_loan_without_loanedAt_starts_today() throws Exception {
        String memberId = registerMember("서연우");
        String bookId = registerBook();

        mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON)
                        .content("{\"bookId\":\"" + bookId + "\",\"memberId\":\"" + memberId + "\"}"))
                .andExpect(status().isCreated())
                .andExpect(jsonPath("$.loanedAt").value(LocalDate.now().toString()))
                .andExpect(jsonPath("$.dueAt").value(LocalDate.now().plusDays(14).toString()));
    }

    @Test
    void returning_on_the_due_date_has_no_late_fee() throws Exception {
        String loanId = loanBook(registerBook(), registerMember("이도윤"), "2026-01-01");

        returnLoan(loanId, "{\"returnedAt\":\"2026-01-15\"}")
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.returnedAt").value("2026-01-15"))
                .andExpect(jsonPath("$.overdueDays").value(0))
                .andExpect(jsonPath("$.lateFee").value(0));
    }

    @Test
    void returning_one_day_late_charges_100() throws Exception {
        String loanId = loanBook(registerBook(), registerMember("한예린"), "2026-01-01");

        returnLoan(loanId, "{\"returnedAt\":\"2026-01-16\"}")
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.overdueDays").value(1))
                .andExpect(jsonPath("$.lateFee").value(100));
    }

    @Test
    void returning_five_days_late_charges_500() throws Exception {
        String loanId = loanBook(registerBook(), registerMember("오세준"), "2026-01-01");

        returnLoan(loanId, "{\"returnedAt\":\"2026-01-20\"}")
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.overdueDays").value(5))
                .andExpect(jsonPath("$.lateFee").value(500));
    }

    @Test
    void returning_without_a_body_uses_today() throws Exception {
        String loanId = loanBook(registerBook(), registerMember("권나은"), "2026-01-01");
        long expectedOverdueDays = ChronoUnit.DAYS.between(LocalDate.of(2026, 1, 15), LocalDate.now());

        mockMvc.perform(post("/loans/{loanId}/return", loanId))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.returnedAt").value(LocalDate.now().toString()))
                .andExpect(jsonPath("$.overdueDays").value(expectedOverdueDays))
                .andExpect(jsonPath("$.lateFee").value(expectedOverdueDays * 100));
    }

    @Test
    void returning_before_the_loan_date_returns_400() throws Exception {
        String loanId = loanBook(registerBook(), registerMember("문하준"), "2026-01-01");

        returnLoan(loanId, "{\"returnedAt\":\"2025-12-31\"}")
                .andExpect(status().isBadRequest());
    }

    org.springframework.test.web.servlet.ResultActions returnLoan(String loanId, String body) throws Exception {
        return mockMvc.perform(post("/loans/{loanId}/return", loanId)
                .contentType(MediaType.APPLICATION_JSON)
                .content(body));
    }

    String loanBook(String bookId, String memberId, String loanedAt) throws Exception {
        String loaned = mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON)
                        .content(loanBody(bookId, memberId, loanedAt)))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        return objectMapper.readTree(loaned).get("loanId").asText();
    }

    String loanBody(String bookId, String memberId, String loanedAt) throws Exception {
        return "{\"bookId\":\"" + bookId + "\",\"memberId\":\"" + memberId + "\",\"loanedAt\":\"" + loanedAt + "\"}";
    }

    String registerMember(String name) throws Exception {
        String registered = mockMvc.perform(post("/members")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"name\":\"" + name + "\"}"))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        return objectMapper.readTree(registered).get("memberId").asText();
    }

    String registerBook() throws Exception {
        String registered = mockMvc.perform(post("/books")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"title\":\"Clean Code\"}"))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        JsonNode book = objectMapper.readTree(registered);
        return book.get("id").asText();
    }
}

